func runExplainExport(ctx context.Context, w, errW io.Writer, opts explainExportOptions) error {
	hasTarget := opts.target != "" || opts.commitRef != "" || opts.checkpointFlag != ""

	switch {
	case opts.transcript || opts.rawTranscript:
